package com.aicoo.care;

import com.aicoo.common.*;
import com.aicoo.security.Policy;
import com.aicoo.security.Policy.Actor;
import com.fasterxml.jackson.annotation.JsonAlias;
import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.aicoo.common.Db.*;

@Service public class CareService {
    public record ChildWrite(@JsonAlias("name") @Size(min=1,max=80)String displayName,@PastOrPresent LocalDate birthDate,@Size(max=256)String photoObjectKey){}
    public record RoutineWrite(@Pattern(regexp="sleep|wake|play|soothe|custom")String type,@Size(min=1,max=100)String title,@Size(max=1000)String note,Instant scheduledAt,Instant endedAt,@Size(max=80)String timezone,@Pattern(regexp="todo|in_progress|done")String status){}
    private final Db db;private final Policy policy;private final Audit audit;private final Idempotency idem;
    public CareService(Db db,Policy policy,Audit audit,Idempotency idem){this.db=db;this.policy=policy;this.audit=audit;this.idem=idem;}
    public Map<String,Object> child(Actor actor,UUID child){var link=policy.require(actor,child,"child:read");var row=db.required("SELECT * FROM children WHERE id=:id",p("id",child),"CHILD_NOT_ACCESSIBLE");var result=view(row,"id","display_name","birth_date","photo_object_key","created_at");result.put("name",row.get("display_name"));result.put("workspaceChildId",link.get("id"));result.put("capabilities",policy.capabilities(actor,child).stream().sorted().toList());audit.record(actor.workspaceId(),actor.userId(),"child.read","child",child);return result;}
    public Object children(Actor actor){return Map.of("items",policy.accessibleChildren(actor,"child:read").stream().map(c->child(actor,c)).toList());}
    @Transactional public Object createChild(Actor actor,ChildWrite body,String key){policy.manager(actor);if(body.displayName()==null||body.displayName().isBlank()||body.birthDate()==null)throw ApiException.invalid("CHILD_FIELDS_REQUIRED");validateBirth(body.birthDate());return idem.execute(actor.membershipId(),key==null?UUID.randomUUID().toString():key,"child.create",body,()->{UUID child=UUID.randomUUID(),link=UUID.randomUUID();db.update("INSERT INTO children(id,display_name,birth_date,photo_object_key,created_by) VALUES(:id,:name,:birth,:photo,:user)",p("id",child,"name",body.displayName().trim(),"birth",body.birthDate(),"photo",body.photoObjectKey(),"user",actor.userId()));db.update("INSERT INTO workspace_children(id,workspace_id,child_id) VALUES(:id,:ws,:child)",p("id",link,"ws",actor.workspaceId(),"child",child));db.update("INSERT INTO child_access_grants(id,workspace_child_id,membership_id,workspace_id,capabilities,valid_from) VALUES(:id,:wc,:m,:ws,cast(:caps as jsonb),now())",p("id",UUID.randomUUID(),"wc",link,"m",actor.membershipId(),"ws",actor.workspaceId(),"caps",db.json(Policy.CAPABILITIES)));audit.record(actor.workspaceId(),actor.userId(),"child.create","child",child);return child(actor,child);});}
    @Transactional public Object updateChild(Actor actor,UUID child,ChildWrite body){policy.require(actor,child,"child:manage");if(body.birthDate()!=null)validateBirth(body.birthDate());if(body.displayName()!=null&&body.displayName().isBlank())throw ApiException.invalid("INVALID_NAME");db.update("UPDATE children SET display_name=COALESCE(:name,display_name),birth_date=COALESCE(:birth,birth_date),photo_object_key=COALESCE(:photo,photo_object_key) WHERE id=:id",p("name",body.displayName(),"birth",body.birthDate(),"photo",body.photoObjectKey(),"id",child));audit.record(actor.workspaceId(),actor.userId(),"child.update","child",child);var row=db.required("SELECT id,display_name,birth_date,photo_object_key FROM children WHERE id=:id",p("id",child),"CHILD_NOT_ACCESSIBLE");return view(row,"id","display_name","birth_date","photo_object_key");}
    private void validateBirth(LocalDate birth){if(birth.isAfter(LocalDate.now(ZoneId.of("Asia/Seoul")))||birth.isBefore(LocalDate.of(2000,1,1)))throw ApiException.invalid("INVALID_BIRTH_DATE");}
    public Object routines(Actor actor,UUID child,LocalDate date){policy.require(actor,child,"routine:read");var params=p("ws",actor.workspaceId(),"child",child);String where="";if(date!=null){params.put("start",date.atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant());params.put("end",date.plusDays(1).atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant());where=" AND scheduled_at>=:start AND scheduled_at<:end";}return Map.of("items",db.list("SELECT * FROM routines WHERE workspace_id=:ws AND child_id=:child AND deleted_at IS NULL"+where+" ORDER BY scheduled_at NULLS LAST,id LIMIT 500",params).stream().map(this::routineView).toList());}
    private Map<String,Object> routineView(Map<String,Object> r){return view(r,"id","child_id","type","title","note","scheduled_at","ended_at","timezone","status","completed_at","created_at","version");}
    @Transactional public Object createRoutine(Actor actor,UUID child,RoutineWrite body,String key){var link=policy.require(actor,child,"routine:write");if(body.type()==null||body.title()==null||body.title().isBlank())throw ApiException.invalid("ROUTINE_FIELDS_REQUIRED");return idem.execute(actor.membershipId(),key==null?UUID.randomUUID().toString():key,"routine.create:"+child,body,()->{UUID id=UUID.randomUUID();String zone=body.timezone()==null?"Asia/Seoul":body.timezone();validZone(zone);validateTimes(body.scheduledAt(),body.endedAt());String status=body.status()==null?"todo":body.status();db.update("INSERT INTO routines(id,workspace_id,workspace_child_id,child_id,type,title,note,scheduled_at,ended_at,timezone,status,completed_at,created_by) VALUES(:id,:ws,:wc,:child,:type,:title,:note,:start,:end,:zone,:status,:completed,:m)",p("id",id,"ws",actor.workspaceId(),"wc",link.get("id"),"child",child,"type",body.type(),"title",body.title().trim(),"note",body.note(),"start",body.scheduledAt(),"end",body.endedAt(),"zone",zone,"status",status,"completed",status.equals("done")?Instant.now():null,"m",actor.membershipId()));return routineView(db.required("SELECT * FROM routines WHERE id=:id",p("id",id),"ROUTINE_NOT_FOUND"));});}
    @Transactional public Object updateRoutine(Actor actor,UUID child,UUID id,RoutineWrite body){policy.require(actor,child,"routine:write");var old=db.required("SELECT * FROM routines WHERE id=:id AND workspace_id=:ws AND child_id=:child AND deleted_at IS NULL FOR UPDATE",p("id",id,"ws",actor.workspaceId(),"child",child),"ROUTINE_NOT_ACCESSIBLE");String zone=body.timezone()==null?text(old,"timezone"):body.timezone();validZone(zone);Instant start=body.scheduledAt()==null?instant(old,"scheduled_at"):body.scheduledAt(),end=body.endedAt()==null?instant(old,"ended_at"):body.endedAt();validateTimes(start,end);if(body.title()!=null&&body.title().isBlank())throw ApiException.invalid("INVALID_TITLE");String status=body.status()==null?text(old,"status"):body.status();db.update("UPDATE routines SET type=COALESCE(:type,type),title=COALESCE(:title,title),note=COALESCE(:note,note),scheduled_at=:start,ended_at=:end,timezone=:zone,status=:status,completed_at=:complete,updated_at=now(),version=version+1 WHERE id=:id",p("type",body.type(),"title",body.title(),"note",body.note(),"start",start,"end",end,"zone",zone,"status",status,"complete",status.equals("done")?(old.get("completed_at")==null?Instant.now():old.get("completed_at")):null,"id",id));return routineView(db.required("SELECT * FROM routines WHERE id=:id",p("id",id),"ROUTINE_NOT_FOUND"));}
    @Transactional public void deleteRoutine(Actor actor,UUID child,UUID id){policy.require(actor,child,"routine:write");if(db.update("UPDATE routines SET deleted_at=now(),updated_at=now(),version=version+1 WHERE id=:id AND workspace_id=:ws AND child_id=:child AND deleted_at IS NULL",p("id",id,"ws",actor.workspaceId(),"child",child))==0)throw ApiException.notFound("ROUTINE_NOT_ACCESSIBLE");audit.record(actor.workspaceId(),actor.userId(),"routine.delete","routine",id);}
    private void validateTimes(Instant start,Instant end){if(end!=null&&(start==null||end.isBefore(start)))throw ApiException.invalid("INVALID_TIME_RANGE");}
    private void validZone(String zone){try{ZoneId.of(zone);}catch(DateTimeException e){throw ApiException.invalid("INVALID_TIMEZONE");}}
    public Object summary(Actor actor,UUID child,LocalDate date){policy.require(actor,child,"child:read");Instant start=date.atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant(),end=date.plusDays(1).atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant();var params=p("ws",actor.workspaceId(),"child",child,"start",start,"end",end);boolean cryAllowed=policy.allowed(actor,child,"cry:read"),detectionAllowed=policy.allowed(actor,child,"detection:read"),routineAllowed=policy.allowed(actor,child,"routine:read");
        var cries=cryAllowed?db.list("SELECT id,started_at,ended_at FROM detection_events WHERE workspace_id=:ws AND child_id=:child AND type='cry' AND NOT cry_retired AND started_at>=:start AND started_at<:end ORDER BY started_at,id",params):List.<Map<String,Object>>of();
        var intervals=(cryAllowed||detectionAllowed)?db.list("SELECT greatest(started_at,:start) AS \"from\",least(COALESCE(ended_at,last_updated_at),:end) AS \"to\" FROM monitoring_sessions WHERE workspace_id=:ws AND child_id=:child AND status='live' AND started_at<:end AND COALESCE(ended_at,last_updated_at)>:start",params):List.<Map<String,Object>>of();
        var routines=routineAllowed?db.list("SELECT * FROM routines WHERE workspace_id=:ws AND child_id=:child AND deleted_at IS NULL AND scheduled_at>=:start AND scheduled_at<:end",params):List.<Map<String,Object>>of();
        var risks=detectionAllowed?db.list("SELECT id FROM detection_events WHERE workspace_id=:ws AND child_id=:child AND type<>'cry' AND severity IN ('immediate','caution','unknown') AND started_at>=:start AND started_at<:end",params):List.<Map<String,Object>>of();
        var durations=cries.stream().filter(r->r.get("ended_at")!=null).mapToLong(r->Duration.between(instant(r,"started_at"),instant(r,"ended_at")).getSeconds()).average();
        List<Map<String,Object>> timeline=new ArrayList<>();for(var cry:cries){var item=view(cry,"id","started_at","ended_at");item.put("feedback",db.list("SELECT response,created_at AS \"createdAt\" FROM care_feedback WHERE event_id=:event AND workspace_id=:ws ORDER BY created_at",p("event",cry.get("id"),"ws",actor.workspaceId())));timeline.add(item);}
        var sleeps=routineAllowed?db.list("SELECT greatest(started_at,:start) AS started_at,least(ended_at,:end) AS ended_at FROM sleep_records WHERE workspace_id=:ws AND child_id=:child AND deleted_at IS NULL AND started_at<:end AND ended_at>:start ORDER BY started_at",params):List.<Map<String,Object>>of();
        long seconds=0;Instant covered=start;
        for(var sleep:sleeps){Instant from=instant(sleep,"started_at"),to=instant(sleep,"ended_at");if(to.isAfter(covered)){seconds+=Duration.between(from.isAfter(covered)?from:covered,to).getSeconds();covered=to;}}
        return p("childId",child,"date",date,"timezone","Asia/Seoul","hasData",!cries.isEmpty()||!intervals.isEmpty()||!routines.isEmpty()||!risks.isEmpty()||!sleeps.isEmpty(),"collectionIntervals",intervals,"cryCount",cryAllowed&&(!cries.isEmpty()||!intervals.isEmpty())?cries.size():null,"averageCryDurationSec",durations.isPresent()?durations.getAsDouble():null,"riskCount",detectionAllowed&&(!risks.isEmpty()||!intervals.isEmpty())?risks.size():null,"completedRoutineCount",routineAllowed&&!routines.isEmpty()?routines.stream().filter(r->"done".equals(r.get("status"))).count():null,"sleepMinutes",sleeps.isEmpty()?null:Math.round(seconds/60.0),"timeline",timeline);
    }
}
